## Membangun REST API

Dalam lesson ini kita membangun REST API lengkap dengan CRUD operations menggunakan in-memory storage.

## Struktur Proyek

```
api/
├── main.go
└── handler/
    └── todo.go
```

## Data Model & Storage

```go
package main

import (
	"encoding/json"
	"net/http"
	"strconv"
	"sync"
)

type Todo struct {
	ID        int    `json:"id"`
	Title     string `json:"title"`
	Completed bool   `json:"completed"`
}

// In-memory store
var (
	mu     sync.RWMutex
	todos  = map[int]*Todo{}
	nextID = 1
)
```

## Handler Implementasi

```go
// GET /todos — list all
func listTodos(w http.ResponseWriter, r *http.Request) {
	mu.RLock()
	defer mu.RUnlock()

	result := make([]*Todo, 0, len(todos))
	for _, t := range todos {
		result = append(result, t)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(result)
}

// POST /todos — create
func createTodo(w http.ResponseWriter, r *http.Request) {
	var input struct {
		Title string `json:"title"`
	}
	if err := json.NewDecoder(r.Body).Decode(&input); err != nil {
		http.Error(w, err.Error(), http.StatusBadRequest)
		return
	}
	if input.Title == "" {
		http.Error(w, "title is required", http.StatusBadRequest)
		return
	}

	mu.Lock()
	todo := &Todo{ID: nextID, Title: input.Title}
	todos[nextID] = todo
	nextID++
	mu.Unlock()

	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(http.StatusCreated)
	json.NewEncoder(w).Encode(todo)
}

// DELETE /todos/{id}
func deleteTodo(w http.ResponseWriter, r *http.Request) {
	idStr := r.PathValue("id")
	id, err := strconv.Atoi(idStr)
	if err != nil {
		http.Error(w, "invalid id", http.StatusBadRequest)
		return
	}

	mu.Lock()
	defer mu.Unlock()
	if _, ok := todos[id]; !ok {
		http.Error(w, "not found", http.StatusNotFound)
		return
	}
	delete(todos, id)
	w.WriteHeader(http.StatusNoContent)
}

func main() {
	mux := http.NewServeMux()
	mux.HandleFunc("GET /todos", listTodos)
	mux.HandleFunc("POST /todos", createTodo)
	mux.HandleFunc("DELETE /todos/{id}", deleteTodo)

	http.ListenAndServe(":8080", mux)
}
```

## Testing dengan curl

```bash
# List todos
curl localhost:8080/todos

# Create todo
curl -X POST localhost:8080/todos -d '{"title":"Learn Go"}' -H 'Content-Type: application/json'

# Delete todo
curl -X DELETE localhost:8080/todos/1
```

